"use client";

import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from "react";
import { cancellationEffectiveAt, MEMBERSHIP_POLICY_VERSION } from "../../lib/membership-policy";
import { subscriptionSite } from "../../lib/subscription-site";
import { ArrowDownLeft, ArrowRight, ArrowUpRight, Check, ChevronDown, ChevronRight, Copy, CreditCard, DoorOpen, FolderHeart, Grid2X2, HeartHandshake, HelpCircle, LayoutGrid, LogOut, Plus, Search, Settings2, ShieldCheck, Sparkles, Users, Wallet, X } from "lucide-react";

type Member = { id: string; name: string; role?: string };
type Subscription = { id: string; name: string; websiteUrl?: string | null; category: string; description: string; totalCents: number; maxSeats: number; activeCount: number; ownerId: string; ownerName: string; memberIds: string[]; myStatus: "owner" | "active" | "pending" | "none"; shareCents: number; prospectiveShareCents?: number; fullShareCents: number; nextDueDate: string; createdAt: string; myPolicyVersion?: string | null; myPolicyAcceptedAt?: string | null; myCancellationRequestedAt?: string | null; myCancellationEffectiveAt?: string | null };
type JoinRequest = { subscriptionId: string; userId: string; userName: string; createdAt?: string };
type AccessState = { enabled: boolean; status: "anonymous" | "unrequested" | "pending" | "approved" | "rejected"; isAdmin: boolean; requestedAt: string | null; updatedAt: string | null; reason: string | null; notificationEmailConfigured: boolean };
type AccessRequest = { userId: string; name: string; email: string; reason: string; status: string; createdAt: string; updatedAt: string };
type BureauState = { access?: AccessState; notificationPreferences?: { enabled: boolean; email: string | null }; user: null | { id: string; name: string; email: string }; workspaces: { id: string; name: string; role: string }[]; workspace: null | { id: string; name: string; role: string; inviteCode?: string }; members: Member[]; subscriptions: Subscription[]; requests: JoinRequest[]; billing: { configured: boolean; mode: string }; payments: { id: string; amountCents: number; status: string; createdAt?: string; updatedAt?: string; period?: string; description?: string }[] };
type BillingState = { configured: boolean; mode: string; ledgerMode?: string; consentVersion?: string; mandateText?: string; consent?: { maxCents?: number; ready?: boolean }; payments: BureauState["payments"]; totals: { collectedCents: number; pendingCents: number } };
type Tab = "discover" | "mine" | "office" | "wallet";
type Modal = "create" | "workspace" | "rename" | "join" | "profile" | "invite" | "how" | "edit" | "payment" | "participate" | "accept-policy" | "leave" | null;
const blank: BureauState = { access: { enabled: true, status: "anonymous", isAdmin: false, requestedAt: null, updatedAt: null, reason: null, notificationEmailConfigured: false }, notificationPreferences: { enabled: false, email: null }, user: null, workspaces: [], workspace: null, members: [], subscriptions: [], requests: [], billing: { configured: false, mode: "disabled" }, payments: [] };
const categories = ["Tout", "Vidéo", "Photo", "Musique", "Design", "IA", "Stockage", "Productivité", "Autre"];
const money = (cents: number) => new Intl.NumberFormat("fr-FR", { style: "currency", currency: "EUR", maximumFractionDigits: cents % 100 ? 2 : 0 }).format(cents / 100);
const date = (value: string) => { const d = new Date(value + (value.length === 10 ? "T12:00:00" : "")); return Number.isNaN(d.getTime()) ? value : new Intl.DateTimeFormat("fr-FR", { day: "numeric", month: "short" }).format(d); };
const fullDate = (value: string) => new Intl.DateTimeFormat("fr-FR", { day: "numeric", month: "long", year: "numeric", timeZone: "Europe/Paris" }).format(new Date(value));
const hasNoticePolicy = (s: Subscription) => s.myPolicyVersion === MEMBERSHIP_POLICY_VERSION && Boolean(s.myPolicyAcceptedAt);
const initials = (s: string) => s.split(/\s+/).map(v => v[0]).join("").slice(0, 2).toUpperCase();
const paymentLabels: Record<string, string> = {paid:"Payé",open:"À régler",ready:"À collecter",creating:"En préparation",draft:"En préparation",blocked_setup:"Autorisation à configurer",blocked_cap:"Plafond à revoir",blocked_minimum:"Montant trop faible",void:"Annulé",no_charge:"Aucun montant dû",refunded:"Remboursé",partially_refunded:"Remboursé en partie",disputed:"Contesté",payment_failed:"Paiement à régulariser",uncollectible:"Impayé",manual_review:"À vérifier"};
const nextMonth = () => { const d = new Date(); d.setMonth(d.getMonth() + 1, 1); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-01`; };
const demo = (): BureauState => ({ access: { enabled: true, status: "approved", isAdmin: false, requestedAt: null, updatedAt: null, reason: null, notificationEmailConfigured: false }, notificationPreferences: { enabled: false, email: null }, user: { id: "demo-moi", name: "Vous", email: "" }, workspaces: [{ id: "demo", name: "Le cercle créatif", role: "admin" }], workspace: { id: "demo", name: "Le cercle créatif", role: "admin", inviteCode: "DEMONSTRATION" }, members: [{ id: "demo-moi", name: "Vous", role: "admin" }, { id: "demo-a", name: "Alex" }, { id: "demo-s", name: "Sam" }, { id: "demo-j", name: "Jo" }], subscriptions: [
  { id: "demo-1", name: "Studio Images", category: "Vidéo", description: "La boîte à outils du studio pour donner vie à toutes les idées.", totalCents: 6000, maxSeats: 6, activeCount: 3, ownerId: "demo-moi", ownerName: "Vous", memberIds: ["demo-moi", "demo-a", "demo-s"], myStatus: "owner", shareCents: 2000, fullShareCents: 1000, nextDueDate: nextMonth(), createdAt: "" },
  { id: "demo-2", name: "Bibliothèque Sonore", category: "Musique", description: "Les bonnes ambiances pour les prochains projets du cercle.", totalCents: 3600, maxSeats: 4, activeCount: 2, ownerId: "demo-a", ownerName: "Alex", memberIds: ["demo-a", "demo-j"], myStatus: "none", shareCents: 1800, fullShareCents: 900, nextDueDate: nextMonth(), createdAt: "" },
  { id: "demo-3", myPolicyVersion: MEMBERSHIP_POLICY_VERSION, myPolicyAcceptedAt: "2026-01-01T00:00:00.000Z", name: "Atelier Typo", category: "Design", description: "Des caractères, des caractères, et encore des caractères.", totalCents: 2400, maxSeats: 4, activeCount: 4, ownerId: "demo-s", ownerName: "Sam", memberIds: ["demo-moi", "demo-a", "demo-s", "demo-j"], myStatus: "active", shareCents: 600, fullShareCents: 600, nextDueDate: nextMonth(), createdAt: "" },
], requests: [], billing: { configured: false, mode: "disabled" }, payments: [] });

function ModalShell({ title, children, close, wide = false, dismissible = true }: { title: string; children: ReactNode; close: () => void; wide?: boolean; dismissible?: boolean }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { const el = ref.current; el?.showModal(); return () => el?.close(); }, []);
  return <dialog ref={ref} className={`bureau-dialog ${wide ? "dialog-wide" : ""}`} onCancel={e => { if (dismissible) close(); else e.preventDefault(); }} onClick={e => { if (dismissible && e.target === e.currentTarget) close(); }}><div className="dialog-header"><h2>{title}</h2><button className="icon-button" aria-label="Fermer" disabled={!dismissible} onClick={close}><X size={21} /></button></div>{children}</dialog>;
}

function SubscriptionMark({ name, websiteUrl }: { name: string; websiteUrl?: string | null }) {
  const site = subscriptionSite(websiteUrl);
  const [failedIcon, setFailedIcon] = useState<string | null>(null);
  const hasIcon = Boolean(site && failedIcon !== site.iconUrl);
  return <span className={`app-mark mark-${Math.abs(name.charCodeAt(0) || 0) % 5}${hasIcon ? " has-site-icon" : ""}`} aria-hidden="true">{site && hasIcon ? <img src={site.iconUrl} alt="" width={32} height={32} loading="lazy" decoding="async" referrerPolicy="no-referrer" onError={() => setFailedIcon(site.iconUrl)}/> : initials(name || "Abonnement")}</span>;
}

export default function BureauApp() {
  const [data, setData] = useState<BureauState>(blank);
  const loadSequence = useRef(0);
  const [isDemo, setDemo] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [toast, setToast] = useState("");
  const [workspaceId, setWorkspaceId] = useState("");
  const [tab, setTab] = useState<Tab>("discover");
  const [category, setCategory] = useState("Tout");
  const [query, setQuery] = useState("");
  const [availableOnly, setAvailableOnly] = useState(false);
  const [modal, setModal] = useState<Modal>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [formError, setFormError] = useState("");
  const [billing, setBilling] = useState<BillingState>({ configured: false, mode: "disabled", payments: [], totals: { collectedCents: 0, pendingCents: 0 } });
  const [billingLoading, setBillingLoading] = useState(false);
  const [invitation, setInvitation] = useState("");
  const [price, setPrice] = useState("60");
  const [subscriptionName, setSubscriptionName] = useState("");
  const [subscriptionNameEdited, setSubscriptionNameEdited] = useState(false);
  const [websiteInput, setWebsiteInput] = useState("");
  const [websiteTouched, setWebsiteTouched] = useState(false);
  const [seats, setSeats] = useState(5);
  const [simSeats, setSimSeats] = useState(3);
  const [accessRequests, setAccessRequests] = useState<AccessRequest[]>([]);
  const [accessReviewLoading, setAccessReviewLoading] = useState(false);
  const [accessReviewError, setAccessReviewError] = useState("");
  const [accessMailConfigured, setAccessMailConfigured] = useState(false);
  const [authEmail, setAuthEmail] = useState("");
  const [authCode, setAuthCode] = useState("");
  const [authStep, setAuthStep] = useState<"credentials" | "verify" | "forgot" | "reset">("credentials");
  const [authMode, setAuthMode] = useState<"signin" | "signup">("signin");
  const [authPassword, setAuthPassword] = useState("");
  const [authPasswordRepeat, setAuthPasswordRepeat] = useState("");
  const [authNotice, setAuthNotice] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [authBusy, setAuthBusy] = useState(false);
  const [authError, setAuthError] = useState("");
  const [authCooldown, setAuthCooldown] = useState(0);
  const accessAllowed = Boolean(data.user && (data.access?.status === "approved" || data.access?.isAdmin));
  const selected = data.subscriptions.find(s => s.id === selectedId);
  const sitePreview = subscriptionSite(websiteInput);
  const websiteInvalid = Boolean(websiteInput.trim() && !sitePreview);
  const selectedSite = subscriptionSite(selected?.websiteUrl);
  const admin = data.workspace?.role === "admin" || data.workspace?.role === "owner";
  const mine = data.subscriptions.filter(s => s.myStatus === "active" || s.myStatus === "owner");
  const monthly = mine.reduce((sum, s) => sum + s.shareCents, 0);
  const savings = mine.reduce((sum, s) => sum + s.totalCents - s.shareCents, 0);

  const load = useCallback(async (id?: string) => {
    const sequence = ++loadSequence.current; setError("");
    try {
      let resp = await fetch(`/api/state${id ? `?workspace=${encodeURIComponent(id)}` : ""}`, { cache: "no-store" });
      let result = await resp.json() as BureauState & { error?: string };
      if (sequence !== loadSequence.current) return;
      if (resp.status === 403 && id) { localStorage.removeItem("embrasse-workspace"); resp = await fetch("/api/state", { cache: "no-store" }); result = await resp.json() as BureauState & { error?: string }; }
      if (!resp.ok) throw new Error(result.error || "Le cercle n’a pas pu se charger.");
      if (sequence !== loadSequence.current) return;
      setData({ ...blank, ...result });
      if (result.workspace?.id) { setWorkspaceId(result.workspace.id); localStorage.setItem("embrasse-workspace", result.workspace.id); }
      return result;
    } catch (e) { if (sequence === loadSequence.current) setError(e instanceof Error ? e.message : "La connexion a été interrompue."); }
    finally { if (sequence === loadSequence.current) setLoading(false); }
  }, []);
  useEffect(() => { const params = new URLSearchParams(location.search); setInvitation(params.get("invite") || ""); if (params.has("payment_setup")) { setTab("wallet"); setToast(params.get("payment_setup") === "complete" ? "Enregistrement transmis. La confirmation du paiement est en cours." : "Enregistrement de la carte annulé."); } void load(localStorage.getItem("embrasse-workspace") || undefined); }, [load]);
  useEffect(() => { if (!toast) return; const id = setTimeout(() => setToast(""), 4200); return () => clearTimeout(id); }, [toast]);
  useEffect(() => { setFormError(""); }, [modal, selectedId]);
  useEffect(() => { if (authCooldown <= 0) return; const timer = setTimeout(() => setAuthCooldown(value => Math.max(0, value - 1)), 1000); return () => clearTimeout(timer); }, [authCooldown]);
  useEffect(() => {
    if (tab !== "wallet" || !workspaceId || isDemo || !accessAllowed) return;
    let cancelled = false; setBillingLoading(true);
    fetch(`/api/billing/state?workspace=${encodeURIComponent(workspaceId)}`, { cache: "no-store" }).then(async response => { const result = await response.json() as BillingState & { error?: string }; if (!response.ok) throw new Error(result.error || "La caisse n’a pas pu se charger."); if (!cancelled) setBilling(result); }).catch(error => { if (!cancelled) setFormError(error.message); }).finally(() => { if (!cancelled) setBillingLoading(false); });
    return () => { cancelled = true; };
  }, [tab, workspaceId, isDemo, accessAllowed]);

  const loadAccessRequests = useCallback(async () => {
    setAccessReviewLoading(true); setAccessReviewError("");
    try {
      const response = await fetch("/api/access/requests", { cache: "no-store" });
      const result = await response.json() as { requests?: AccessRequest[]; notificationEmailConfigured?: boolean; error?: string };
      if (!response.ok) throw new Error(result.error || "Les demandes d’accès n’ont pas pu se charger.");
      setAccessRequests((result.requests || []).filter(request => request.status === "pending")); setAccessMailConfigured(Boolean(result.notificationEmailConfigured));
    } catch (error) { setAccessReviewError(error instanceof Error ? error.message : "La connexion a été interrompue."); }
    finally { setAccessReviewLoading(false); }
  }, []);
  useEffect(() => {
    if (!accessAllowed || !data.access?.enabled || !data.access.isAdmin || isDemo) { setAccessRequests([]); return; }
    if (tab === "office" || !data.workspace) void loadAccessRequests();
  }, [accessAllowed, data.access?.enabled, data.access?.isAdmin, isDemo, tab, Boolean(data.workspace), loadAccessRequests]);

  function clearPasswords() { setAuthPassword(""); setAuthPasswordRepeat(""); setShowPassword(false); }
  function resetAuth(step: "credentials" | "verify" | "forgot" | "reset", mode = authMode) {
    clearPasswords(); setAuthCode(""); setAuthError(""); setAuthNotice(""); setAuthStep(step); setAuthMode(mode);
  }
  function authFailure(status: number, result: { error?: string; message?: string; code?: string }, context: "credentials" | "code" | "signup" = "credentials") {
    if (result.code === "WEAK_PASSWORD") return "Ce mot de passe est trop facile à deviner. Choisissez une phrase plus longue avec plusieurs mots, sans répétition évidente.";
    if (result.code === "PASSWORD_TOO_SHORT") return "Choisissez une phrase unique d’au moins douze caractères.";
    if (result.code === "PASSWORD_TOO_LONG") return "Le mot de passe doit contenir au maximum 128 caractères.";
    if (result.code === "AUTH_EMAIL_UNAVAILABLE") return result.error || "L’envoi des e-mails doit encore être activé. Réessayez une fois le service raccordé.";
    if (status === 429 || result.code?.includes("TOO_MANY")) return "Trop de tentatives. Patientez un instant avant de réessayer.";
    if (result.code?.includes("EXPIRED")) return "Ce code a expiré. Demandez-en un nouveau.";
    if (context === "code" && (status === 400 || status === 401 || result.code?.includes("OTP"))) return "Ce code n’est pas valide. Vérifiez les six chiffres reçus par e-mail.";
    if (context === "signup") return "Le compte n’a pas pu être créé. Essayez de vous connecter ou de réinitialiser votre mot de passe.";
    if (status === 400 || status === 401 || status === 403) return "E-mail ou mot de passe incorrect. Vérifiez vos informations.";
    return "La connexion n’a pas abouti. Réessayez dans un instant.";
  }
  async function authRequest(path: string, body: object) {
    const response = await fetch(`/api/auth/${path}`, { method: "POST", credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
    const result = await response.json().catch(() => ({})) as { success?: boolean; error?: string; message?: string; code?: string };
    return { response, result };
  }
  async function sendVerificationCode() {
    const { response, result } = await authRequest("email-otp/send-verification-otp", { email: authEmail.trim(), type: "email-verification" });
    if (!response.ok) throw new Error(authFailure(response.status, result, "code"));
    setAuthCooldown(60); setAuthCode("");
  }
  async function validateChosenPassword() {
    const { chosenPasswordStrength } = await import("../../lib/password-strength");
    const email = authEmail.trim().toLowerCase();
    const result = await chosenPasswordStrength(authPassword, [email, email.split("@")[0]]);
    if (!result.ok) throw new Error(result.message || "Choisissez une phrase plus longue et unique pour votre mot de passe.");
  }
  async function submitCredentials(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); setAuthBusy(true); setAuthError(""); setAuthNotice("");
    try {
      if (authMode === "signup") { if (authPassword !== authPasswordRepeat) throw new Error("Les deux mots de passe ne correspondent pas."); await validateChosenPassword(); }
      const { response, result } = await authRequest(authMode === "signup" ? "sign-up/email" : "sign-in/email", { email: authEmail.trim(), password: authPassword, ...(authMode === "signup" ? { name: "Créatif" } : {}) });
      if (!response.ok) {
        if (result.code === "EMAIL_NOT_VERIFIED") {
          clearPasswords(); setAuthStep("verify"); setAuthNotice("Votre adresse doit être vérifiée. Saisissez votre code ou demandez-en un nouveau."); return;
        }
        throw new Error(authFailure(response.status, result, authMode === "signup" ? "signup" : "credentials"));
      }
      clearPasswords();
      if (authMode === "signup") { setAuthStep("verify"); setAuthCode(""); setAuthCooldown(60); }
      else await load();
    } catch (error) { setAuthError(error instanceof Error && !(error instanceof TypeError) ? error.message : "La connexion a été interrompue. Réessayez."); }
    finally { setAuthBusy(false); }
  }
  async function resendVerification() {
    setAuthBusy(true); setAuthError("");
    try { await sendVerificationCode(); }
    catch (error) { setAuthError(error instanceof Error && !(error instanceof TypeError) ? error.message : "La demande a été interrompue. Réessayez."); }
    finally { setAuthBusy(false); }
  }
  async function verifyEmailCode(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); setAuthBusy(true); setAuthError("");
    try {
      const { response, result } = await authRequest("email-otp/verify-email", { email: authEmail.trim(), otp: authCode.trim() });
      if (!response.ok) throw new Error(authFailure(response.status, result, "code"));
      clearPasswords(); setAuthCode(""); setAuthStep("credentials"); setAuthMode("signin");
      const state = await load();
      if (!state?.user) setAuthNotice("Votre e-mail est vérifié. Vous pouvez maintenant vous connecter.");
    } catch (error) { setAuthError(error instanceof Error && !(error instanceof TypeError) ? error.message : "La vérification a été interrompue. Réessayez."); }
    finally { setAuthBusy(false); }
  }
  async function requestPasswordReset(e?: FormEvent<HTMLFormElement>) {
    e?.preventDefault(); setAuthBusy(true); setAuthError(""); setAuthNotice("");
    try {
      const { response, result } = await authRequest("email-otp/request-password-reset", { email: authEmail.trim() });
      if (!response.ok) throw new Error(authFailure(response.status, result));
      clearPasswords(); setAuthStep("reset"); setAuthCode(""); setAuthCooldown(60);
    } catch (error) { setAuthError(error instanceof Error && !(error instanceof TypeError) ? error.message : "La demande a été interrompue. Réessayez."); }
    finally { setAuthBusy(false); }
  }
  async function confirmPasswordReset(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); setAuthBusy(true); setAuthError("");
    try {
      if (authPassword !== authPasswordRepeat) throw new Error("Les deux mots de passe ne correspondent pas.");
      await validateChosenPassword();
      const { response, result } = await authRequest("email-otp/reset-password", { email: authEmail.trim(), otp: authCode.trim(), password: authPassword });
      if (!response.ok) throw new Error(authFailure(response.status, result, "code"));
      resetAuth("credentials", "signin"); setAuthNotice("Votre mot de passe est mis à jour. Connectez-vous avec le nouveau.");
    } catch (error) { setAuthError(error instanceof Error && !(error instanceof TypeError) ? error.message : "La réinitialisation a été interrompue. Réessayez."); }
    finally { setAuthBusy(false); }
  }
  async function signOut() {
    setAuthBusy(true); setFormError("");
    try {
      const response = await fetch("/api/auth/sign-out", { method: "POST", credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: "{}" });
      if (!response.ok) throw new Error("La déconnexion n’a pas abouti. Réessayez.");
      setSelectedId(null); setModal(null); setData(blank); setTab("discover"); resetAuth("credentials", "signin"); localStorage.removeItem("embrasse-workspace"); setWorkspaceId("");
      if (!["localhost", "127.0.0.1", "[::1]"].includes(window.location.hostname)) { window.location.assign("/signout-with-chatgpt?return_to=%2F"); return; }
      await load();
    } catch (error) { setFormError(error instanceof Error ? error.message : "La déconnexion a été interrompue."); }
    finally { setAuthBusy(false); }
  }

  async function submitAccess(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); const form = new FormData(e.currentTarget); setBusy(true); setFormError("");
    try {
      await mutate("/api/access/request", { name: form.get("name"), reason: form.get("reason") || "", notificationOptIn: Boolean(form.get("notificationOptIn")) });
      setToast("Votre demande d’accès est enregistrée.");
    } catch (error) { setFormError(error instanceof Error ? error.message : "La demande n’a pas pu être enregistrée."); }
    finally { setBusy(false); }
  }
  async function reviewAccess(request: AccessRequest, decision: "approve" | "reject") {
    const ok = await action(`/api/access/${encodeURIComponent(request.userId)}/${decision}`, decision === "approve" ? "Accès accordé." : "Demande refusée.");
    if (ok) await loadAccessRequests();
  }

  async function mutate(path: string, body?: object, method = "POST") {
    if (isDemo) return demoMutation(path, body as Record<string, unknown> | undefined, method);
    const response = await fetch(path, { method, headers: { "Content-Type": "application/json" }, body: method === "DELETE" ? undefined : JSON.stringify(body ?? {}) });
    const result = await response.json() as { error?: string; workspaceId?: string; workspace?: { id: string } };
    if (!response.ok) throw new Error(result.error || "Cette action n’a pas pu être effectuée.");
    const id = result.workspaceId || result.workspace?.id || workspaceId;
    await load(id || undefined); return result;
  }
  function demoMutation(path: string, body?: Record<string, unknown>, method?: string) {
    if (path === "/api/profile") setData(prev => ({ ...prev, user: prev.user && { ...prev.user, name: String(body?.name) } }));
    else if (path === "/api/profile/notifications") setData(prev => ({ ...prev, notificationPreferences: { enabled: Boolean(body?.enabled), email: prev.user?.email || null } }));
    else if (path === "/api/subscriptions") {
      const sub = { ...body, id: `demo-${Date.now()}`, activeCount: 1, ownerId: "demo-moi", ownerName: "Vous", memberIds: ["demo-moi"], myStatus: "owner", shareCents: Number(body?.totalCents), fullShareCents: Math.ceil(Number(body?.totalCents) / Number(body?.maxSeats)), createdAt: "" } as Subscription;
      setData(prev => ({ ...prev, subscriptions: [...prev.subscriptions, sub] }));
    } else {
      const id = path.split("/")[3];
      setData(prev => ({ ...prev, subscriptions: method === "DELETE" ? prev.subscriptions.filter(s => s.id !== id) : prev.subscriptions.map(s => s.id !== id ? s : path.endsWith("/request") ? { ...s, myStatus: "pending", myPolicyVersion: MEMBERSHIP_POLICY_VERSION, myPolicyAcceptedAt: new Date().toISOString() } : path.endsWith("/accept-policy") ? { ...s, myPolicyVersion: MEMBERSHIP_POLICY_VERSION, myPolicyAcceptedAt: s.myPolicyAcceptedAt || new Date().toISOString() } : path.endsWith("/cancel-leave") ? { ...s, myCancellationRequestedAt: null, myCancellationEffectiveAt: null } : path.endsWith("/leave") ? s.myStatus === "pending" ? { ...s, myStatus: "none" } : { ...s, myCancellationRequestedAt: new Date().toISOString(), myCancellationEffectiveAt: s.myCancellationEffectiveAt || cancellationEffectiveAt(new Date()) } : method === "PATCH" ? { ...s, ...body, shareCents: Math.ceil(Number(body?.totalCents) / s.activeCount), fullShareCents: Math.ceil(Number(body?.totalCents) / Number(body?.maxSeats)) } : s) }));
    }
    return {};
  }
  async function action(path: string, message: string, body?: object, method?: string) {
    setBusy(true); setFormError("");
    try { await mutate(path, body, method); setToast(isDemo ? "Démo : " + message : message); return true; }
    catch (e) { setFormError(e instanceof Error ? e.message : "Une erreur est survenue."); return false; }
    finally { setBusy(false); }
  }
  async function formSubmit(e: FormEvent<HTMLFormElement>, kind: Modal) {
    e.preventDefault(); const f = new FormData(e.currentTarget); setBusy(true); setFormError("");
    try {
      if (kind === "participate" || kind === "accept-policy") {
        if (!selected || !f.get("membershipPolicy")) throw new Error("Acceptez la règle de participation pour envoyer votre demande.");
        await mutate(`/api/subscriptions/${selected.id}/${kind === "accept-policy" ? "accept-policy" : "request"}`, { policyAccepted: true, policyVersion: MEMBERSHIP_POLICY_VERSION });
        setModal(null); setToast(kind === "accept-policy" ? "Règle de participation acceptée." : isDemo ? "Démo : demande envoyée, aucun paiement." : "Demande envoyée au responsable."); return;
      }
      if (kind === "leave") {
        if (!selected) throw new Error("Choisissez un abonnement.");
        await mutate(`/api/subscriptions/${selected.id}/leave`);
        setModal(null); setToast(hasNoticePolicy(selected) ? isDemo ? "Démo : départ programmé, aucun paiement." : "Départ programmé. La date de fin est enregistrée." : "Vous avez quitté le groupe."); return;
      }
      if (kind === "payment") {
        if (!paymentData.configured || isDemo) throw new Error("Le compte de collecte doit d’abord être raccordé.");
        const maxCents = Math.round(Number(String(f.get("maxAmount")).replace(",", ".")) * 100);
        if (!f.get("consent")) throw new Error("Votre autorisation est nécessaire pour enregistrer un moyen de paiement.");
        if (!Number.isSafeInteger(maxCents) || maxCents < monthly) throw new Error("Le plafond doit couvrir votre participation prévisionnelle.");
        const response = await fetch("/api/billing/setup", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ workspaceId, maxCents, consent: true, consentVersion: paymentData.consentVersion }) });
        const result = await response.json() as { error?: string; url: string }; if (!response.ok) throw new Error(result.error || "Le paiement n’a pas pu être préparé.");
        const url = new URL(result.url); if (url.protocol !== "https:" || !["checkout.stripe.com", "billing.stripe.com"].includes(url.hostname)) throw new Error("Le lien de paiement reçu est invalide.");
        window.location.assign(url.href); return;
      }
      if (kind === "workspace") await mutate("/api/workspaces", { name: f.get("name") });
      if (kind === "rename") await mutate(`/api/workspaces/${workspaceId}`, { name: f.get("name") }, "PATCH");
      if (kind === "join") await mutate("/api/workspaces/join", { code: f.get("code") });
      if (kind === "profile") { await mutate("/api/profile", { name: f.get("name") }); await mutate("/api/profile/notifications", { enabled: Boolean(f.get("notifications")) }); }
      if (kind === "create" || kind === "edit") {
        if (websiteInvalid) {
          setWebsiteTouched(true);
          e.currentTarget.querySelector<HTMLInputElement>('input[name="websiteUrl"]')?.focus();
          throw new Error("Vérifiez le lien du site, par exemple adobe.com. Vous pouvez aussi laisser ce champ vide.");
        }
        const totalCents = Math.round(Number(price.replace(",", ".")) * 100);
        if (!Number.isSafeInteger(totalCents) || totalCents < 1) throw new Error("Indiquez un prix mensuel supérieur à zéro.");
        await mutate(kind === "edit" ? `/api/subscriptions/${selectedId}` : "/api/subscriptions", { workspaceId, name: subscriptionName.trim(), websiteUrl: sitePreview?.websiteUrl ?? null, category: f.get("category"), description: f.get("description"), totalCents, maxSeats: seats, nextDueDate: f.get("nextDueDate") }, kind === "edit" ? "PATCH" : "POST");
      }
      setModal(null); setToast(isDemo ? "Démo mise à jour, sans enregistrement." : "C’est enregistré.");
    } catch (e) { setFormError(e instanceof Error ? e.message : "Une erreur est survenue."); }
    finally { setBusy(false); }
  }
  function updateSubscriptionWebsite(value: string) {
    setWebsiteInput(value); setWebsiteTouched(false);
    const site = subscriptionSite(value);
    if (!subscriptionNameEdited) {
      if (site) setSubscriptionName(site.name);
      else if (!value.trim()) setSubscriptionName("");
    }
  }
  function openCreate() {
    setPrice("60"); setSeats(5); setSimSeats(3); setSubscriptionName(""); setSubscriptionNameEdited(false); setWebsiteInput(""); setWebsiteTouched(false); setModal("create");
  }
  function openEdit() {
    if (!selected) return;
    setPrice(String(selected.totalCents / 100)); setSeats(selected.maxSeats); setSimSeats(selected.activeCount); setSubscriptionName(selected.name); setSubscriptionNameEdited(true); setWebsiteInput(selected.websiteUrl || ""); setWebsiteTouched(false); setModal("edit");
  }
  async function copyInvite() {
    try { await navigator.clipboard.writeText(`${location.origin}/?invite=${encodeURIComponent(data.workspace?.inviteCode || "")}`); setToast("Lien d’invitation copié."); }
    catch { setFormError("La copie n’a pas fonctionné. Sélectionnez le lien ci-dessous."); }
  }
  function exitDemo() { setDemo(false); setSelectedId(null); setTab("discover"); setData(blank); setLoading(true); void load(workspaceId || undefined); }
  const visible = (tab === "mine" ? data.subscriptions.filter(s => s.myStatus !== "none") : data.subscriptions).filter(s => (category === "Tout" || s.category === category) && (!query || `${s.name} ${s.description} ${s.ownerName}`.toLowerCase().includes(query.toLowerCase())) && (!availableOnly || s.activeCount < s.maxSeats));
  const pending = data.requests || [];
  const paymentData = isDemo ? { ...billing, configured: false, payments: [], totals: { collectedCents: 0, pendingCents: 0 } } : billing;
  const intro = !data.user && !loading && !error;

  function accessReview() {
    if (!data.access?.enabled || !data.access.isAdmin || isDemo) return null;
    return <section className="access-review" aria-labelledby="access-review-title"><div className="access-review-heading"><div><p className="eyebrow">ACCÈS AU SITE</p><h2 id="access-review-title">Les demandes d’entrée.</h2><p>Seules les personnes approuvées peuvent utiliser les abonnements du cercle.</p></div><button className="button secondary small" disabled={accessReviewLoading} onClick={() => void loadAccessRequests()}>{accessReviewLoading ? "Chargement…" : "Actualiser"}</button></div>{!accessMailConfigured && <p className="notification-hint">Les alertes par e-mail ne sont pas encore configurées. Les demandes restent consultables ici.</p>}{accessReviewError && <p className="form-error" role="alert">{accessReviewError}</p>}{!accessReviewLoading && !accessReviewError && !accessRequests.length && <p className="muted">Aucune demande en attente.</p>}<div className="access-request-list">{accessRequests.map(request => <article className="access-request" key={request.userId}><div className="access-request-person"><span className="avatar">{initials(request.name)}</span><div><h3>{request.name}</h3><a href={`mailto:${request.email}`}>{request.email}</a><small>Demande du {fullDate(request.createdAt)}</small></div></div>{request.reason && <p className="access-request-reason">{request.reason}</p>}<div className="access-request-actions"><button className="button secondary small" disabled={busy} onClick={() => void reviewAccess(request, "reject")}>Refuser</button><button className="button primary small" disabled={busy} onClick={() => void reviewAccess(request, "approve")}><Check size={15}/> Autoriser l’accès</button></div></article>)}</div></section>;
  }

  function card(s: Subscription) {
    const full = s.activeCount >= s.maxSeats;
    const joinsNext = (s.myStatus === "none" || s.myStatus === "pending") && !full;
    const cardShare = joinsNext ? (s.prospectiveShareCents ?? Math.ceil(s.totalCents / (s.activeCount + 1))) : s.shareCents;
    return <button className={`subscription-card ${full ? "is-full" : ""}`} key={s.id} onClick={() => setSelectedId(s.id)}>
      <div className="card-top"><SubscriptionMark name={s.name} websiteUrl={s.websiteUrl}/><span className={`seat-tag ${full ? "full" : ""}`}>{s.myStatus === "pending" ? "Demande envoyée" : full ? "Complet" : `${s.maxSeats - s.activeCount} place${s.maxSeats - s.activeCount > 1 ? "s" : ""} libre${s.maxSeats - s.activeCount > 1 ? "s" : ""}`}</span></div>
      <span className="card-category">{s.category}</span><h3>{s.name}</h3><p className="card-description">{s.description || `Proposé par ${s.ownerName}`}</p>
      <div className="card-price"><strong>{money(cardShare)}</strong><span>/ personne / mois</span></div><p className="card-price-context">{joinsNext ? "Votre part en rejoignant le groupe" : s.myStatus === "owner" || s.myStatus === "active" ? "Votre part au prochain cycle" : "Part actuelle des participants"}</p>{s.myCancellationEffectiveAt && <p className="departure-tag">Départ le {fullDate(s.myCancellationEffectiveAt)}</p>}<div className="card-comparison"><span>Total : {money(s.totalCents)}/mois</span><span>À {s.maxSeats} : ≈ {money(s.fullShareCents)}/pers.</span></div>
      <div className="seat-track"><span style={{ width: `${Math.min(100, s.activeCount / s.maxSeats * 100)}%` }} /></div>
      <div className="card-bottom"><div className="avatar-stack">{s.memberIds.slice(0, 3).map((id, i) => <span className={`avatar avatar-${i}`} key={id}>{initials(data.members.find(m => m.id === id)?.name || "M")}</span>)}<small>{s.activeCount}/{s.maxSeats}</small></div><span className="card-arrow">{s.myStatus === "owner" || s.myStatus === "active" ? "Mon abonnement" : "Voir le groupe"}<ArrowUpRight size={16} /></span></div>
    </button>;
  }

  return <div className="bureau-app">
    <aside className="bureau-sidebar"><a className="bureau-brand" href="/">embrasse</a><div className="sidebar-label">À PLUSIEURS, C’EST MIEUX.</div>{accessAllowed && <nav aria-label="Menu du cercle">{([{ id: "discover", name: "Découvrir", icon: Grid2X2 }, { id: "mine", name: "Mes abonnements", icon: FolderHeart }, { id: "office", name: "Le cercle", icon: Users }, { id: "wallet", name: "La caisse", icon: Wallet }] as const).map(item => <button key={item.id} className={tab === item.id ? "active" : ""} onClick={() => { setTab(item.id); setQuery(""); setCategory("Tout"); }}><item.icon size={19} /><span>{item.name}</span>{item.id === "mine" && mine.length > 0 && <small>{mine.length}</small>}</button>)}</nav>}
      <div className="sidebar-note"><div className="note-flower">✳</div><strong>Les outils se partagent.<br/>Les idées se multiplient.</strong><button onClick={() => setModal("how")}>Comment ça marche <ArrowUpRight size={14} /></button></div>
      <div className="sidebar-footer">{data.user ? <button className="profile-button" onClick={() => setModal("profile")}><span className="avatar self">{initials(data.user.name)}</span><span><strong>{data.user.name}</strong><small>{isDemo ? "Compte de démonstration" : "Mon profil"}</small></span><Settings2 size={16} /></button> : <span className="sidebar-footnote">Des créatifs. Des outils. Du commun.</span>}</div>
    </aside>
    <div className="bureau-main"><header className="bureau-topbar"><div className="workspace-control"><span className="workspace-icon"><DoorOpen size={16} /></span>{data.workspaces.length > 1 ? <select aria-label="Changer de cercle" value={workspaceId} onChange={e => { setWorkspaceId(e.target.value); if (!isDemo) void load(e.target.value); }}>{data.workspaces.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}</select> : <span>{data.workspace?.name || "Le cercle EMBRASSE"}</span>}<span className="topbar-separator">/</span><span className="topbar-section">{tab === "discover" ? "Abonnements" : tab === "mine" ? "Mes abonnements" : tab === "office" ? "Membres" : "Cotisations"}</span></div><div className="topbar-actions">{isDemo && <button className="demo-exit" onClick={exitDemo}>Quitter la démo <X size={14} /></button>}{data.user && !isDemo && <button className="signout" disabled={authBusy} onClick={() => void signOut()} aria-label="Se déconnecter"><LogOut size={17} /></button>}<span className="topbar-embrasse">EMBRASSE / COMMUN</span></div></header>
      <main className="bureau-content">
        {isDemo && <div className="demo-banner"><Sparkles size={16} /><span><strong>Vous explorez une démo.</strong> Les outils, les personnes et les montants sont fictifs. Aucun paiement.</span><button className="demo-exit" onClick={exitDemo}>Revenir à mon cercle <ArrowRight size={15}/></button></div>}
        {error && <div className="error-banner" role="alert"><span>{error}</span><button onClick={() => { setLoading(true); void load(workspaceId || undefined); }}>Réessayer</button></div>}
        {loading ? <div className="loading-view" role="status"><span className="spinner"/><p>On ouvre le cercle…</p></div> : intro ? <>
          <div className="intro-kicker"><span className="green-dot"/>LE CERCLE EMBRASSE</div><section className="intro-hero auth-hero"><div><h1>Les bons outils.<br/><span>Entre créatifs.</span></h1><p>Un cercle pour partager vos abonnements créatifs.<br/>Retrouvez les bonnes personnes, partagez le coût et créez ensemble.</p><p className="connection-note"><ShieldCheck size={15}/> {data.access?.enabled ? "Votre e-mail, votre mot de passe. Accès après validation de votre profil." : "Votre e-mail, votre mot de passe. Retrouvez les créatifs du cercle."}</p></div><section className="email-auth" aria-labelledby="email-auth-title"><span className="auth-step">{authStep === "credentials" ? "VOTRE COMPTE" : authStep === "verify" ? "VÉRIFICATION DE L’E-MAIL" : "RÉCUPÉRATION DU COMPTE"}</span><h2 id="email-auth-title">{authStep === "credentials" ? authMode === "signin" ? "Retrouvez votre cercle." : "Créez votre compte." : authStep === "verify" ? "Vérifiez votre e-mail." : authStep === "forgot" ? "Un nouveau départ." : "Choisissez un nouveau mot de passe."}</h2>{authNotice && <p className="auth-notice" role="status">{authNotice}</p>}{authStep === "credentials" ? <><div className="auth-mode-tabs" aria-label="Connexion ou inscription"><button className={authMode === "signin" ? "active" : ""} type="button" disabled={authBusy} onClick={() => resetAuth("credentials", "signin")}>Se connecter</button><button className={authMode === "signup" ? "active" : ""} type="button" disabled={authBusy} onClick={() => resetAuth("credentials", "signup")}>Créer un compte</button></div><form key={authMode} onSubmit={e => void submitCredentials(e)}><p>{authMode === "signup" ? data.access?.enabled ? "Choisissez vos identifiants. Après vérification de votre e-mail, vous complèterez votre profil pour demander l’accès." : "Choisissez vos identifiants, vérifiez votre e-mail puis connectez-vous pour retrouver le cercle." : "Connectez-vous avec votre e-mail et le mot de passe que vous avez choisi."}</p><label>Votre adresse e-mail<input disabled={authBusy} type="email" name="email" value={authEmail} onChange={e => { setAuthEmail(e.target.value); setAuthError(""); }} autoComplete="email" required placeholder="vous@exemple.fr" maxLength={254}/></label><label>Votre mot de passe<input disabled={authBusy} type={showPassword ? "text" : "password"} name="password" value={authPassword} onChange={e => { setAuthPassword(e.target.value); setAuthError(""); }} minLength={authMode === "signup" ? 12 : undefined} maxLength={128} autoComplete={authMode === "signup" ? "new-password" : "current-password"} required/></label>{authMode === "signup" && <><p className="password-help">12 caractères minimum. Choisissez une phrase unique que vous n’utilisez pas ailleurs.</p><label>Confirmez votre mot de passe<input disabled={authBusy} type={showPassword ? "text" : "password"} name="passwordRepeat" value={authPasswordRepeat} onChange={e => { setAuthPasswordRepeat(e.target.value); setAuthError(""); }} minLength={12} maxLength={128} autoComplete="new-password" required/></label></>}<label className="auth-show-password"><input disabled={authBusy} type="checkbox" checked={showPassword} onChange={e => setShowPassword(e.target.checked)}/><span>Afficher le mot de passe</span></label>{authError && <p className="form-error" role="alert">{authError}</p>}<button className="button primary full-width" disabled={authBusy}>{authBusy ? "Un instant…" : authMode === "signup" ? "Créer mon compte" : "Me connecter"}<ArrowRight size={17}/></button>{authMode === "signin" && <div className="auth-secondary-actions"><button type="button" disabled={authBusy} onClick={() => resetAuth("forgot")}>Mot de passe oublié ?</button></div>}<p className="auth-fineprint">{authMode === "signup" ? "Un code reçu par e-mail servira uniquement à vérifier votre adresse." : data.access?.enabled ? "Votre accès reste réservé aux profils approuvés par l’équipe." : "Votre adresse e-mail doit être vérifiée pour vous connecter."}</p></form></> : authStep === "verify" ? <form onSubmit={e => void verifyEmailCode(e)}><p>Vérifiez l’adresse <strong className="auth-email-value">{authEmail}</strong> avec le code reçu par e-mail.</p><label>Code de vérification à six chiffres<input disabled={authBusy} className="auth-code" name="code" inputMode="numeric" autoComplete="one-time-code" value={authCode} onChange={e => { setAuthCode(e.target.value.replace(/[^0-9]/g, "").slice(0, 6)); setAuthError(""); }} pattern="[0-9]{6}" minLength={6} maxLength={6} required autoFocus placeholder="000000"/></label>{authError && <p className="form-error" role="alert">{authError}</p>}<button className="button primary full-width" disabled={authBusy || authCode.length !== 6}>{authBusy ? "Vérification…" : "Vérifier mon e-mail"}<ArrowRight size={17}/></button><div className="auth-secondary-actions"><button type="button" disabled={authBusy || authCooldown > 0} onClick={() => void resendVerification()}>{authCooldown > 0 ? `Renvoyer dans ${authCooldown} s` : "Demander un nouveau code"}</button><button type="button" disabled={authBusy} onClick={() => resetAuth("credentials", "signin")}>Retour à la connexion</button></div><p className="auth-fineprint">Ce code vérifie votre adresse, il ne remplace pas votre mot de passe. Il expire après dix minutes.</p></form> : authStep === "forgot" ? <form onSubmit={e => void requestPasswordReset(e)}><p>Indiquez votre e-mail pour demander un code de réinitialisation.</p><label>Votre adresse e-mail<input disabled={authBusy} type="email" name="email" value={authEmail} onChange={e => { setAuthEmail(e.target.value); setAuthError(""); }} autoComplete="email" required placeholder="vous@exemple.fr" maxLength={254}/></label>{authError && <p className="form-error" role="alert">{authError}</p>}<button className="button primary full-width" disabled={authBusy}>{authBusy ? "Un instant…" : "Demander la réinitialisation"}<ArrowRight size={17}/></button><div className="auth-secondary-actions"><button type="button" disabled={authBusy} onClick={() => resetAuth("credentials", "signin")}>Retour à la connexion</button></div></form> : <form onSubmit={e => void confirmPasswordReset(e)}><p>Si un compte correspond à <strong className="auth-email-value">{authEmail}</strong>, un code permet de choisir un nouveau mot de passe.</p><label>Code à six chiffres<input disabled={authBusy} className="auth-code" name="code" inputMode="numeric" autoComplete="one-time-code" value={authCode} onChange={e => { setAuthCode(e.target.value.replace(/[^0-9]/g, "").slice(0, 6)); setAuthError(""); }} pattern="[0-9]{6}" minLength={6} maxLength={6} required autoFocus placeholder="000000"/></label><label>Nouveau mot de passe<input disabled={authBusy} type={showPassword ? "text" : "password"} name="newPassword" value={authPassword} onChange={e => { setAuthPassword(e.target.value); setAuthError(""); }} minLength={12} maxLength={128} autoComplete="new-password" required/></label><p className="password-help">12 caractères minimum. Choisissez une phrase unique que vous n’utilisez pas ailleurs.</p><label>Confirmez le nouveau mot de passe<input disabled={authBusy} type={showPassword ? "text" : "password"} name="passwordRepeat" value={authPasswordRepeat} onChange={e => { setAuthPasswordRepeat(e.target.value); setAuthError(""); }} minLength={12} maxLength={128} autoComplete="new-password" required/></label><label className="auth-show-password"><input disabled={authBusy} type="checkbox" checked={showPassword} onChange={e => setShowPassword(e.target.checked)}/><span>Afficher le mot de passe</span></label>{authError && <p className="form-error" role="alert">{authError}</p>}<button className="button primary full-width" disabled={authBusy || authCode.length !== 6}>{authBusy ? "Enregistrement…" : "Enregistrer mon nouveau mot de passe"}<ArrowRight size={17}/></button><div className="auth-secondary-actions"><button type="button" disabled={authBusy || authCooldown > 0} onClick={() => void requestPasswordReset()}>{authCooldown > 0 ? `Renvoyer dans ${authCooldown} s` : "Demander un nouveau code"}</button><button type="button" disabled={authBusy} onClick={() => resetAuth("credentials", "signin")}>Retour à la connexion</button></div></form>}</section></section>
          <div className="intro-features"><article><span>01</span><h2>On se retrouve.</h2><p>Un cercle privé pour se retrouver entre créatifs.</p></article><article><span>02</span><h2>On fait de la place.</h2><p>Chacun propose ses outils, leur prix et le nombre de places.</p></article><article><span>03</span><h2>On partage la note.</h2><p>La part de chacun s’ajuste avec le nombre de participants.</p></article></div><div className="intro-bottom"><HeartHandshake size={23}/><p>Moins d’abonnements dans son coin.<br/><strong>Plus de choses à faire ensemble.</strong></p></div>
        </> : data.user && !accessAllowed ? <section className="access-gate"><div className="access-gate-intro"><span className="access-gate-icon"><ShieldCheck size={27}/></span><p className="eyebrow">ENTRE CRÉATIFS</p><h1>{data.access?.status === "pending" ? <>Votre place<br/>se prépare.</> : data.access?.status === "rejected" ? <>Votre demande<br/>n’a pas été retenue.</> : <>On fait<br/>connaissance ?</>}</h1><p>{data.access?.status === "pending" ? "Votre demande est enregistrée. L’équipe doit la valider avant que vous puissiez accéder aux abonnements." : data.access?.status === "rejected" ? "L’accès au site n’a pas été accordé. Vous pouvez contacter l’équipe pour faire le point sur votre demande." : "Présentez-vous à l’équipe. Une fois votre accès approuvé, vous pourrez rejoindre le cercle et ses abonnements."}</p></div>{data.access?.status === "pending" || data.access?.status === "rejected" ? <div className="access-status-card"><h2>{data.access.status === "pending" ? "Validation en attente" : "Accès non accordé"}</h2><p className="verified-email"><ShieldCheck size={16}/>{data.notificationPreferences?.email || data.user.email}</p>{data.access.requestedAt && <p>Demande enregistrée le {fullDate(data.access.requestedAt)}.</p>}<p>La réponse sera visible sur cette page.</p>{!data.access.notificationEmailConfigured && <p className="notification-hint">Les notifications par e-mail ne sont pas encore configurées.</p>}<button className="button secondary full-width" disabled={busy} onClick={() => void load()}>Vérifier ma demande <ArrowRight size={16}/></button></div> : <form className="access-request-form" onSubmit={e => void submitAccess(e)}><h2>Demander l’accès</h2><label>Votre nom<input name="name" defaultValue={data.user.name === "Créatif" ? "" : data.user.name} maxLength={60} required autoComplete="name"/></label><label>Votre e-mail vérifié<input type="email" value={data.notificationPreferences?.email || data.user.email} readOnly autoComplete="email"/></label><p className="field-help">Cette adresse a été vérifiée par e-mail.</p><label>Votre univers créatif <span>(facultatif)</span><textarea name="reason" rows={3} maxLength={500} placeholder="Réalisation, photo, montage, design, musique…"/></label><label className="consent-label"><input type="checkbox" name="notificationOptIn"/><span>Recevoir un e-mail lorsqu’une personne est acceptée dans l’un de mes abonnements, avec ma nouvelle part estimée.</span></label><p className="form-fineprint">Vos informations servent à valider votre accès et à vous prévenir des changements de groupe. Vous pourrez modifier vos notifications dans votre profil.</p>{!data.access?.notificationEmailConfigured && <p className="notification-hint">Les e-mails ne sont pas encore activés. Votre demande sera bien enregistrée sur le site.</p>}{formError && <p className="form-error" role="alert">{formError}</p>}<button className="button primary full-width" disabled={busy}>{busy ? "Enregistrement…" : "Envoyer ma demande"}<ArrowRight size={17}/></button></form>}</section> : data.user && !data.workspace ? <>
          {accessReview()}
          <div className="section-heading"><p className="eyebrow">BIENVENUE {data.user.name.toUpperCase()}</p><h1>Le commun,<br/>ça commence ici.</h1><p>Créez votre cercle ou rejoignez des créatifs avec leur invitation.</p></div><div className="onboarding-grid"><article><span className="onboard-icon"><Plus size={26}/></span><h2>Créer un cercle</h2><p>Votre espace privé pour rassembler les personnes et leurs abonnements.</p><button className="button primary" onClick={() => setModal("workspace")}>Créer mon espace <ArrowRight size={17}/></button></article><article><span className="onboard-icon soft"><Users size={26}/></span><h2>Rejoindre les copains</h2><p>Vous avez reçu un lien ou un code ? C’est par ici.</p><button className="button secondary" onClick={() => setModal("join")}>Entrer mon invitation <ArrowRight size={17}/></button></article></div>
        </> : data.workspace && <>
          {tab === "discover" || tab === "mine" ? <>
            <div className="page-heading"><div><p className="eyebrow">{tab === "mine" ? "VOTRE PETIT COLLECTIF" : "LES ABONNEMENTS DU CERCLE"}</p><h1>{tab === "mine" ? <>Les outils<br/>que l’on partage.</> : <>Les bons outils.<br/><span>Entre créatifs.</span></>}</h1><p>{tab === "mine" ? "Vos participations, vos demandes, vos prochaines échéances." : "Une place pour chacun. Un coût partagé. Plus de possibilités."}</p></div><button className="button primary" onClick={openCreate}><Plus size={18}/> Proposer un abonnement</button></div>
            <div className="summary-strip"><div><span>Ma part mensuelle</span><strong>{money(monthly)}<small>/ mois</small></strong></div><div><span>Mes abonnements</span><strong>{mine.length.toString().padStart(2, "0")}<small>en commun</small></strong></div><div><span>Économie théorique</span><strong>{money(savings)}<small>/ mois à plusieurs</small></strong><button className="info-tooltip" onClick={() => setModal("how")} aria-label="Comment est calculée l’économie ?"><HelpCircle size={14}/></button></div><div className="summary-message"><span className="mini-flower">✳</span><span>Seul, on paie tout.<br/><strong>Ensemble, on partage.</strong></span></div></div>
            <div className="catalog-toolbar"><label className="search-field"><Search size={17}/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Chercher un outil, un nom…" aria-label="Rechercher un abonnement"/>{query && <button onClick={() => setQuery("")} aria-label="Effacer la recherche"><X size={15}/></button>}</label><label className="availability"><input type="checkbox" checked={availableOnly} onChange={e => setAvailableOnly(e.target.checked)}/><span>Places disponibles</span></label></div>
            <div className="category-tabs" aria-label="Catégories">{categories.map(c => <button key={c} className={category === c ? "active" : ""} onClick={() => setCategory(c)}>{c}</button>)}<span className="result-count">{visible.length} abonnement{visible.length > 1 ? "s" : ""}</span></div>
            {visible.length ? <div className="subscriptions-grid">{visible.map(card)}<button className="propose-card" onClick={openCreate}><span><Plus size={26}/></span><h3>Une place à partager ?</h3><p>Proposez un outil aux copains<br/>et partagez la prochaine facture.</p><strong>Ajouter un abonnement <ArrowUpRight size={16}/></strong></button></div> : <div className="empty-catalog"><span className="empty-symbol">✳</span><h2>{query || category !== "Tout" || availableOnly ? "Aucun outil de ce côté." : tab === "mine" ? "Votre premier groupe vous attend." : "Le premier outil, c’est vous."}</h2><p>{query || category !== "Tout" || availableOnly ? "Essayez une autre recherche ou retirez un filtre." : "Proposez un abonnement ou invitez les copains à partager les leurs."}</p><button className="button primary" onClick={openCreate}><Plus size={17}/> Proposer un abonnement</button></div>}
            <div className="catalog-footnote"><ShieldCheck size={15}/><span>Le nombre de places est défini par le responsable selon la formule de l’abonnement.</span></div>
          </> : tab === "office" ? <>
            {accessReview()}
            <div className="page-heading"><div><p className="eyebrow">LES IDÉES SE PARTAGENT</p><h1>Le cercle.</h1><p>{data.members.length} personne{data.members.length > 1 ? "s" : ""}. Des idées à mettre en commun.</p></div>{data.workspace.inviteCode && <button className="button primary" onClick={() => setModal("invite")}><Plus size={18}/> Inviter les copains</button>}</div>
            <div className="members-list">{data.members.map((m, i) => <div className="member-row" key={m.id}><span className={`avatar large avatar-${i % 3}`}>{initials(m.name)}</span><div><strong>{m.name}</strong><small>{m.id === data.user?.id ? "C’est vous" : "Membre du cercle"}</small></div><span className="role-pill">{m.role === "admin" || m.role === "owner" ? "Responsable" : "Membre"}</span><span className="member-sub-count">{data.subscriptions.filter(s => s.memberIds.includes(m.id)).length} abonnement(s)</span>{admin && m.id !== data.user?.id && !isDemo && <button className="remove-member" aria-label={`Retirer ${m.name} du cercle`} disabled={busy} onClick={() => { if (window.confirm(`Retirer ${m.name} de ce cercle ?`)) void action(`/api/workspaces/${workspaceId}/remove-member`, "Membre retiré du cercle.", { userId: m.id }); }}><X size={16}/></button>}</div>)}</div>
            {pending.length > 0 && <section className="request-panel"><h2>Les demandes à valider <span>{pending.length}</span></h2>{pending.map(r => <div className="request-row" key={`${r.subscriptionId}-${r.userId}`}><span className="avatar">{initials(r.userName)}</span><p><strong>{r.userName}</strong><small>souhaite rejoindre {data.subscriptions.find(s => s.id === r.subscriptionId)?.name}</small></p><button className="button secondary small" disabled={busy} onClick={() => void action(`/api/subscriptions/${r.subscriptionId}/reject`, "Demande refusée.", { userId: r.userId })}>Refuser</button><button className="button primary small" disabled={busy} onClick={() => void action(`/api/subscriptions/${r.subscriptionId}/approve`, "Bienvenue dans le groupe.", { userId: r.userId })}><Check size={15}/> Accepter</button></div>)}</section>}
            <div className="office-actions">{admin && !isDemo && <button className="button secondary" disabled={busy} onClick={() => setModal("rename")}><Settings2 size={16}/> Renommer le cercle</button>}{data.access?.isAdmin && !isDemo && <button className="button secondary" onClick={() => { setData(demo()); setDemo(true); setSelectedId(null); setTab("discover"); }}>Explorer la démo locale <Sparkles size={16}/></button>}<button className="button secondary" onClick={() => setModal("workspace")}><Plus size={16}/> Créer un autre cercle</button><button className="button secondary" onClick={() => setModal("join")}><Users size={16}/> Rejoindre un cercle</button></div>
          </> : <>
            <div className="page-heading"><div><p className="eyebrow">LA NOTE, EN TOUTE CLARTÉ</p><h1>La caisse<br/>commune.</h1><p>Une participation mensuelle qui continue jusqu’à votre départ programmé.</p></div><span className="payment-mode"><span className="green-dot"/> {paymentData.configured ? paymentData.mode === "test" ? "Mode test — aucun paiement réel" : "Paiements configurés" : "Paiements et relances non activés"}</span></div>
            <div className="wallet-layout"><section className="wallet-balance"><Wallet size={25}/><p>Ma participation prévisionnelle</p><strong>{money(monthly)}<small>/ mois</small></strong><div className="wallet-divider"/><span>{mine.length} abonnement(s) en commun</span><p className="wallet-note">Le montant est recalculé selon les participants au prochain 1er du mois.</p></section><section className="payment-setup"><span className="setup-icon"><CreditCard size={28}/></span><h2>{paymentData.configured ? "Vos cotisations" : "Les paiements automatiques se préparent."}</h2><p>{paymentData.configured ? "Enregistrez votre moyen de paiement et fixez un plafond. Votre part sera calculée le 1er de chaque mois." : "Un seul enregistrement, puis un paiement mensuel ajusté au groupe : c’est le fonctionnement prévu. Le collecteur et le service de paiement doivent d’abord être validés."}</p><div className="setup-status"><span className="status-ring"/><div><strong>{paymentData.configured ? paymentData.consent?.ready ? "Autorisation enregistrée" : "Autorisation à configurer" : "Aucun prélèvement actif"}</strong><small>{paymentData.configured ? paymentData.consent?.ready ? `Plafond accepté : ${money(paymentData.consent.maxCents || 0)} par mois.` : "Choisissez un plafond avant de valider votre autorisation." : "Vos participations sont enregistrées, aucun argent n’est débité."}</small></div></div><button className="button secondary full-width" disabled={billingLoading} onClick={() => setModal("payment")}><CreditCard size={16}/>{paymentData.configured ? "Configurer mes paiements" : "Préparer les paiements"}</button>{paymentData.configured && paymentData.consent?.ready && <button className="button text-button danger full-width" disabled={busy} onClick={async () => { if (!window.confirm("Arrêter les prochains prélèvements automatiques de ce cercle ?")) return; setBusy(true); try { const response = await fetch("/api/billing/revoke", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ workspaceId }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error || "L’autorisation n’a pas pu être retirée."); setBilling(prev => ({ ...prev, consent: prev.consent ? { ...prev.consent, ready: false } : undefined })); setToast("Autorisation retirée pour les prochaines collectes."); } catch (e) { setFormError(e instanceof Error ? e.message : "Une erreur est survenue."); } finally { setBusy(false); } }}>Arrêter les prélèvements automatiques</button>}<p className="setup-hint">Départ avec au moins un mois de préavis, à une échéance mensuelle. Le retrait d’une autorisation bancaire reste distinct de la fin d’une participation.</p></section></div>
            <section className="payment-safeguards" aria-labelledby="payment-safeguards-title"><div className="safeguards-heading"><ShieldCheck size={21}/><div><h2 id="payment-safeguards-title">Prévoir les imprévus.</h2><p>Un seul paiement mensuel par personne pour limiter les frais. Protections prévues pour la mise en service.</p></div><span className="role-pill">À mettre en place</span></div><ol><li><span>01</span><div><strong>Payer avant l’accès</strong><p>Un premier paiement confirmé avant d’ouvrir l’accès au service.</p></div></li><li><span>02</span><div><strong>Préparer le mois suivant</strong><p>Une avance et une réserve commune pour limiter les sommes avancées par le responsable.</p></div></li><li><span>03</span><div><strong>Traiter les impayés</strong><p>Détection, nouvelles tentatives et relances. Un recouvrement externe nécessitera un service distinct ; il ne garantit pas le paiement.</p></div></li></ol><p className="form-fineprint">Aucune réserve n’a été encaissée. Les relances et le recouvrement ne sont pas actifs.</p></section>
            <section className="payment-history"><div className="history-heading"><h2>Mes prochaines parts</h2><span>Prévision, avant encaissement</span></div>{mine.length ? mine.map(s => <div className="payment-row" key={s.id}><span className="payment-symbol"><ArrowUpRight size={18}/></span><div><strong>{s.name}</strong><small>{s.myCancellationEffectiveAt ? `Participation jusqu’au ${fullDate(s.myCancellationEffectiveAt)}, date de départ` : `${s.activeCount} participant(s) · prochain 1er du mois`}</small></div><span>{money(s.shareCents)}</span></div>) : <p className="muted">Rejoignez un abonnement pour voir vos prochaines parts ici.</p>}</section><section className="payment-history"><div className="history-heading"><h2>Historique des cotisations{(paymentData.ledgerMode || paymentData.mode) === "test" ? " de test" : ""}</h2><span>{money(paymentData.totals?.collectedCents || 0)} confirmés{(paymentData.ledgerMode || paymentData.mode) === "test" ? " en test" : ""}</span></div>{paymentData.payments.length ? paymentData.payments.map(p => <div className="payment-row" key={p.id}><span className="payment-symbol"><ArrowDownLeft size={18}/></span><div><strong>{p.description || "Cotisation"}</strong><small>{p.period || (p.updatedAt ? date(p.updatedAt) : p.createdAt ? date(p.createdAt) : "")}</small></div><span>{money(p.amountCents)}</span><span className="role-pill">{paymentLabels[p.status] || "À vérifier"}</span></div>) : <div className="history-empty"><CreditCard size={23}/><p>Aucune cotisation encaissée pour le moment.</p></div>}</section>
          </>}
          {formError && !selected && !modal && <div className="error-banner" role="alert">{formError}</div>}
        </>}
        <footer className="app-footer"><span>embrasse / commun</span><span>Les bonnes choses se partagent.</span></footer>
      </main>
    </div>
    {toast && <div className="toast" role="status"><Check size={16}/>{toast}</div>}
    {modal && <ModalShell title={modal === "create" ? "Une place à partager." : modal === "edit" ? "Modifier l’abonnement" : modal === "rename" ? "Renommer le cercle." : modal === "workspace" ? "Votre cercle commence ici." : modal === "join" ? "Retrouver les copains." : modal === "profile" ? "Comment on vous appelle ?" : modal === "invite" ? "La porte est ouverte." : modal === "payment" ? "Vos cotisations, simplement." : modal === "accept-policy" ? "La règle de participation." : modal === "participate" ? "Rejoindre ce groupe." : modal === "leave" ? "Programmer mon départ." : "Le commun, simplement."} close={() => setModal(null)} dismissible={!busy} wide={modal === "create" || modal === "edit"}>
      {modal === "payment" && !paymentData.configured ? <div className="dialog-body"><div className="setup-icon"><CreditCard size={28}/></div><h3 className="payment-connect-title">Collecteur et paiement à valider.</h3><p className="dialog-description">Le compte Revolut commun ne permet pas, à lui seul, de prélever les membres. Il faut d’abord un collecteur accepté par le prestataire, puis raccorder et tester les paiements récurrents.</p><div className="setup-status"><span className="status-ring"/><div><strong>Aucun prélèvement actif</strong><small>Le paiement est prévu chaque mois jusqu’à votre départ, avec au moins un mois de préavis. Aucune carte n’est débitée pour le moment.</small></div></div><button className="button primary full-width" onClick={() => setModal(null)}>Compris</button></div> : modal === "how" ? <div className="dialog-body how-content"><div><span>01</span><p><strong>Un espace entre créatifs.</strong>Invitez les copains à rejoindre votre espace privé.</p></div><div><span>02</span><p><strong>Le bon nombre de places.</strong>Chaque responsable indique le prix mensuel et la capacité de sa formule.</p></div><div><span>03</span><p><strong>La note divisée entre vous.</strong>Le total est partagé entre les participants, au centime près. La part évolue à la prochaine collecte, le 1er du mois.</p></div><div><span>04</span><p><strong>Le départ se prévoit.</strong>La participation continue chaque mois jusqu’au départ. Une demande de départ prend effet à une échéance mensuelle, après au moins un mois de préavis. La date exacte est affichée avant confirmation.</p></div><p className="help-footnote">L’économie théorique compare le prix complet de chaque outil à votre part actuelle. Les encaissements resteront inactifs tant que la caisse n’est pas raccordée.</p></div> : modal === "invite" ? <div className="dialog-body"><p className="dialog-description">Envoyez ce lien aux personnes de votre cercle. Elles pourront créer leur profil et vous rejoindre.</p><label>Votre lien d’invitation<input readOnly value={`${typeof location !== "undefined" ? location.origin : ""}/?invite=${encodeURIComponent(data.workspace?.inviteCode || "")}`} onFocus={e => e.target.select()}/></label><button className="button primary full-width" onClick={() => void copyInvite()}><Copy size={17}/> Copier le lien</button>{admin && !isDemo && <button className="button text-button danger full-width" disabled={busy} onClick={() => { if (window.confirm("Remplacer le lien d’invitation ? L’ancien lien ne permettra plus de rejoindre le cercle.")) void action(`/api/workspaces/${workspaceId}/rotate-invite`, "Nouveau lien créé. L’ancien lien est désactivé."); }}>Remplacer le lien d’invitation</button>}{formError && <p className="form-error" role="alert">{formError}</p>}</div> : <form className="dialog-body" onSubmit={e => void formSubmit(e, modal)}>
        {(modal === "participate" || modal === "accept-policy") && selected ? <><p className="dialog-description">{modal === "accept-policy" ? <>Vous participez déjà à <strong>{selected.name}</strong>. Cette règle de préavis s’appliquera après votre accord.</> : <>Votre demande pour <strong>{selected.name}</strong> sera transmise au responsable du groupe. Votre participation commencera après sa validation.</>}</p><div className="payment-estimate"><span>{modal === "accept-policy" ? "Votre part actuelle" : "Votre part estimée après votre arrivée"}</span><strong>{money(modal === "accept-policy" ? selected.shareCents : selected.prospectiveShareCents ?? Math.ceil(selected.totalCents / (selected.activeCount + 1)))} / mois</strong></div><div className="membership-terms"><strong>Une participation mensuelle, jusqu’à votre départ.</strong><p>Le montant est partagé entre les participants et peut évoluer au prochain cycle. Pour partir, prévoyez au moins un mois de préavis ; votre départ prend effet à une échéance mensuelle.</p><p>La date exacte vous sera présentée avant confirmation. Vous conservez votre place et participez aux parts jusqu’à cette date.</p></div><label className="consent-label"><input type="checkbox" name="membershipPolicy" required/><span>J’ai lu et j’accepte cette règle de participation et de préavis.</span></label><p className="form-fineprint">Cet accord n’autorise aucun débit bancaire. Les encaissements et les relances restent désactivés tant que le collecteur et le service de paiement ne sont pas validés.</p></> : modal === "leave" && selected ? <><p className="dialog-description">Vous souhaitez arrêter votre participation à <strong>{selected.name}</strong>.</p><div className="payment-estimate departure-estimate"><span>{hasNoticePolicy(selected) ? "Votre départ prendra effet le" : "Votre départ prendra effet"}</span><strong>{hasNoticePolicy(selected) ? fullDate(cancellationEffectiveAt(new Date())) : "Dès votre confirmation"}</strong></div><div className="membership-terms"><strong>{hasNoticePolicy(selected) ? "Au moins un mois pour organiser la suite." : "Votre participation précède la règle de préavis."}</strong>{hasNoticePolicy(selected) ? <><p>Vous gardez votre place et restez dans le calcul des parts jusqu’à cette date. Le montant peut évoluer selon le groupe.</p><p>Vous pourrez annuler ce départ avant sa prise d’effet.</p></> : <p>Vous n’avez pas accepté la nouvelle règle. Aucun préavis ne vous est imposé rétroactivement.</p>}<p>Aucune somme n’est prélevée tant que les paiements ne sont pas activés.</p></div></> : modal === "payment" ? <><p className="dialog-description">Une carte enregistrée une fois. Une seule cotisation, avec le détail de vos abonnements, chaque 1er du mois.</p><div className="payment-estimate"><span>Votre prochaine part estimée</span><strong>{money(monthly)} / mois</strong></div><label>Mon plafond mensuel (€)<input name="maxAmount" inputMode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" defaultValue={paymentData.consent?.maxCents ? paymentData.consent.maxCents / 100 : Math.ceil(Math.max(monthly, 1000) / 100)} required/></label><label className="consent-label"><input type="checkbox" name="consent" required/><span>{paymentData.mandateText || "J’autorise le prélèvement mensuel de mes parts, recalculées selon les participants, dans la limite de mon plafond. Si ce plafond est dépassé, une nouvelle autorisation sera nécessaire."}</span></label><p className="form-fineprint">Le moyen de paiement et l’autorisation sont gérés sur la page sécurisée du prestataire retenu. Aucune donnée bancaire complète n’est enregistrée sur ce site.</p></> : (modal === "create" || modal === "edit") ? <><div className="subscription-site-field"><label htmlFor="subscription-website">Lien du site <span className="optional-label">facultatif</span></label><input id="subscription-website" name="websiteUrl" inputMode="url" autoComplete="url" autoCapitalize="none" spellCheck={false} value={websiteInput} onChange={e => updateSubscriptionWebsite(e.target.value)} onBlur={() => setWebsiteTouched(true)} maxLength={2048} placeholder="Ex. : adobe.com" aria-invalid={websiteTouched && websiteInvalid ? true : undefined} aria-describedby={websiteTouched && websiteInvalid ? "subscription-website-error" : "subscription-website-help"} autoFocus/><p className="field-help" id="subscription-website-help">Collez le lien pour proposer le nom et afficher l’icône. Le nom reste modifiable.</p>{websiteTouched && websiteInvalid && <p className="site-field-error" id="subscription-website-error" role="alert">Indiquez un lien de site public valide, par exemple adobe.com, ou laissez le champ vide.</p>}{sitePreview && <div className="subscription-site-preview" aria-live="polite"><SubscriptionMark name={subscriptionName || sitePreview.name} websiteUrl={sitePreview.websiteUrl}/><div><strong>{subscriptionName || sitePreview.name}</strong><span>{sitePreview.hostname}</span></div><span className="site-preview-badge">Aperçu</span></div>}</div><div className="form-two"><label>Nom de l’abonnement<input name="name" placeholder="Ex. : bibliothèque musicale" value={subscriptionName} onChange={e => { setSubscriptionName(e.target.value); setSubscriptionNameEdited(Boolean(e.target.value.trim())); }} maxLength={80} required/></label><label>Catégorie<select name="category" defaultValue={modal === "edit" ? selected?.category : "Design"}>{categories.slice(1).map(c => <option key={c}>{c}</option>)}</select></label></div><label>Quelques mots pour les copains<textarea name="description" placeholder="Ce qu’on peut faire avec cet outil…" maxLength={600} rows={2} defaultValue={modal === "edit" ? selected?.description : ""}/></label><div className="form-two"><label>Prix total par mois (€)<input value={price} onChange={e => setPrice(e.target.value)} name="price" inputMode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" required/></label><label>Renouvellement du fournisseur<input type="date" name="nextDueDate" defaultValue={modal === "edit" ? selected?.nextDueDate : nextMonth()} required/></label></div><div className="range-label"><label htmlFor="maxSeats">Nombre maximal de personnes</label><strong>{seats}</strong></div><input className="range-input" id="maxSeats" type="range" min={modal === "edit" ? selected?.activeCount || 1 : 1} max={100} value={seats} onChange={e => { setSeats(Number(e.target.value)); setSimSeats(Math.min(simSeats, Number(e.target.value))); }}/><p className="field-help">Le nombre de places prévues par votre formule.</p><div className="split-preview"><div><span>Si vous êtes {Math.min(simSeats, seats)}…</span><strong>{money(Math.ceil((Number(price.replace(",", ".")) || 0) * 100 / Math.min(simSeats, seats)))}<small>/ personne / mois</small></strong></div><label>Simuler le groupe<input type="range" min={1} max={seats} value={Math.min(simSeats, seats)} onChange={e => setSimSeats(Number(e.target.value))}/><span>1 personne <span>{seats} personnes</span></span></label></div><p className="form-fineprint">Le coût est réparti entre les participants. Les changements s’appliquent à la collecte du prochain 1er du mois.</p></> : (modal === "workspace" || modal === "rename") ? <><p className="dialog-description">{modal === "rename" ? "Choisissez le nom qui sera affiché pour tous les membres de votre cercle." : "Un espace privé où réunir vos abonnements et les créatifs avec qui vous partagez vos outils."}</p><label>Nom du cercle<input name="name" placeholder="Ex. : Le cercle des images…" defaultValue={modal === "rename" ? data.workspace?.name : ""} maxLength={80} required autoFocus/></label></> : modal === "join" ? <><p className="dialog-description">Collez le code d’invitation transmis par le responsable du cercle.</p><label>Code d’invitation<input name="code" defaultValue={invitation} placeholder="Votre code d’invitation" required autoFocus autoComplete="off"/></label></> : <><p className="dialog-description">C’est le nom que verront les autres membres du cercle.</p><label>Votre nom<input name="name" defaultValue={data.user?.name} maxLength={60} required autoFocus/></label><label>Votre e-mail vérifié<input type="email" value={data.notificationPreferences?.email || data.user?.email || ""} readOnly/></label><p className="field-help">Cette adresse a été vérifiée par un code envoyé par e-mail.</p><label className="consent-label"><input type="checkbox" name="notifications" defaultChecked={data.notificationPreferences?.enabled || false}/><span>Recevoir un e-mail lorsqu’une personne est acceptée dans l’un de mes abonnements, avec ma part estimée au prochain cycle.</span></label><p className="form-fineprint">L’arrivée doit être approuvée par le responsable du groupe. Une simple demande n’est pas une nouvelle participation.</p>{!data.access?.notificationEmailConfigured && <p className="notification-hint">Les envois d’e-mails ne sont pas encore configurés. Votre préférence sera enregistrée.</p>}</>}
        {formError && <p className="form-error" role="alert">{formError}</p>}<div className="form-actions"><button type="button" className="button secondary" disabled={busy} onClick={() => setModal(null)}>Annuler</button><button className="button primary" disabled={busy}>{busy ? "Un instant…" : modal === "accept-policy" ? "Accepter la règle" : modal === "participate" ? "Accepter et demander une place" : modal === "leave" ? "Confirmer mon départ" : modal === "payment" ? "Enregistrer ma carte" : modal === "create" ? "Partager cet abonnement" : modal === "workspace" ? "Créer mon cercle" : modal === "join" ? "Rejoindre le cercle" : "Enregistrer"}<ArrowRight size={17}/></button></div></form>}
    </ModalShell>}
    {selected && !modal && <ModalShell title={selected.name} close={() => setSelectedId(null)} dismissible={!busy} wide><div className="dialog-body subscription-detail"><div className="detail-service"><SubscriptionMark name={selected.name} websiteUrl={selected.websiteUrl}/><div><strong>{selected.name}</strong>{selectedSite && <span>{selectedSite.hostname}</span>}</div>{selectedSite && <a className="button secondary small" href={selectedSite.websiteUrl} target="_blank" rel="noopener noreferrer" referrerPolicy="no-referrer">Ouvrir le site <ArrowUpRight size={15}/></a>}</div><div className="detail-category"><span className="seat-tag">{selected.category}</span><span>Proposé par {selected.ownerName}</span></div><p className="detail-description">{selected.description || "Un outil à partager entre créatifs."}</p><div className="detail-price"><strong>{money(selected.shareCents)}<small>/ personne / mois</small></strong><span>{money(selected.totalCents)} au total<br/>{selected.activeCount} participant(s)</span></div><div className="seat-track"><span style={{ width: `${selected.activeCount / selected.maxSeats * 100}%` }}/></div><div className="detail-seat-label"><span>{selected.activeCount} / {selected.maxSeats} places occupées</span><strong>À {selected.maxSeats} : {money(selected.fullShareCents)} / personne</strong></div><div className="detail-members"><h3>Dans ce groupe</h3><div>{selected.memberIds.map((id, i) => <span key={id}><span className={`avatar avatar-${i % 3}`}>{initials(data.members.find(m => m.id === id)?.name || "Membre")}</span>{data.members.find(m => m.id === id)?.name || "Membre"}{id === selected.ownerId && <small>Responsable</small>}</span>)}</div></div><div className="due-row"><span>Échéance du fournisseur</span><strong>{date(selected.nextDueDate)}</strong></div>
      {selected.myStatus === "active" && !hasNoticePolicy(selected) && !selected.myCancellationEffectiveAt && <div className="membership-terms legacy-policy"><strong>Une nouvelle règle pour prévoir les départs.</strong><p>Votre participation existait avant le préavis. Vous pouvez accepter cette règle pour la suite ; votre départ reste immédiat sans cet accord.</p><button className="button secondary small" onClick={() => setModal("accept-policy")}>Lire et accepter la règle</button></div>}
      {selected.myCancellationEffectiveAt && <div className="departure-notice"><ShieldCheck size={20}/><div><strong>Départ programmé le {fullDate(selected.myCancellationEffectiveAt)}</strong><p>Votre place reste active et votre part continue d’être calculée jusqu’à cette date.</p></div></div>}
      {(selected.myStatus === "owner" || admin) && pending.filter(r => r.subscriptionId === selected.id).length > 0 && <div className="detail-requests"><h3>Demandes pour ce groupe</h3>{pending.filter(r => r.subscriptionId === selected.id).map(r => <div className="request-row" key={r.userId}><p><strong>{r.userName}</strong></p><button className="button secondary small" disabled={busy} onClick={() => void action(`/api/subscriptions/${selected.id}/reject`, "Demande refusée.", { userId: r.userId })}>Refuser</button><button className="button primary small" disabled={busy} onClick={() => void action(`/api/subscriptions/${selected.id}/approve`, "Place attribuée.", { userId: r.userId })}>Accepter</button></div>)}</div>}
      {formError && <p className="form-error" role="alert">{formError}</p>}{selected.myStatus === "none" && selected.activeCount < selected.maxSeats && <p className="join-estimate">En rejoignant le groupe : <strong>{money(selected.prospectiveShareCents ?? Math.ceil(selected.totalCents / (selected.activeCount + 1)))} / mois</strong>, selon les participants à la prochaine collecte.</p>}<div className="detail-actions">{selected.myStatus === "owner" || admin ? <><button className="button secondary" onClick={openEdit}><Settings2 size={16}/> Modifier</button><button className="button text-button danger" disabled={busy} onClick={() => { if (window.confirm("Archiver cet abonnement et fermer le groupe ?")) void action(`/api/subscriptions/${selected.id}`, "Abonnement archivé.", undefined, "DELETE").then(ok => { if (ok) setSelectedId(null); }); }}>Archiver</button></> : null}{selected.myStatus !== "owner" && (selected.myStatus === "active" || selected.myStatus === "pending" ? <button className="button secondary" disabled={busy} onClick={() => selected.myStatus === "pending" ? void action(`/api/subscriptions/${selected.id}/leave`, "Demande annulée.") : selected.myCancellationEffectiveAt ? void action(`/api/subscriptions/${selected.id}/cancel-leave`, "Départ annulé. Votre participation continue.") : setModal("leave")}>{selected.myStatus === "pending" ? "Annuler ma demande" : selected.myCancellationEffectiveAt ? "Annuler mon départ" : hasNoticePolicy(selected) ? "Programmer mon départ" : "Quitter le groupe"}</button> : <button className="button primary full-width" disabled={busy || selected.activeCount >= selected.maxSeats} onClick={() => setModal("participate")}><Plus size={17}/>{selected.activeCount >= selected.maxSeats ? "Ce groupe est complet" : "Demander une place"}</button>)}</div><p className="form-fineprint">La part est recalculée au prochain cycle mensuel selon les personnes du groupe. Le départ prend effet à une échéance mensuelle après au moins un mois de préavis. La date fournisseur reste distincte du calendrier des cotisations.</p></div></ModalShell>}
  </div>;
}
